def _trailing_comma_is_harmless_after(leaf: Leaf) -> bool:
    """Return True if adding a comma right after `leaf` keeps the code's meaning.

    This looks at the bracket that closes the expression ending with `leaf`. A
    trailing comma in a call, a def, an import, a list, a set or a dict does not
    change anything. In a parenthesized expression or a subscript, it turns the
    content into a tuple unless it is one already.
    """
    node: LN = leaf
    while node.next_sibling is None:
        if node.parent is None:
            return False
        node = node.parent
    closing = node.next_sibling
    if closing.type not in CLOSING_BRACKETS or closing.parent is None:
        return False

    container = closing.parent
    if container.type == syms.atom and closing.type == token.RPAR:
        content = closing.prev_sibling
        return (
            content is not None
            and content.type == syms.testlist_gexp
            and any(child.type == token.COMMA for child in content.children)
        )
    if container.type == syms.trailer and closing.type == token.RSQB:
        content = closing.prev_sibling
        return content is not None and content.type == syms.subscriptlist

    return True


